1	type Cell = [number, number]; // [x, y]
2	
3	function cellEquals([x, y]: Cell, [otherX, otherY]: Cell): boolean {
4	  return x === otherX && y === otherY;
5	}
6	
7	function contains(cells: Cell[], cell: Cell): boolean {
8	  return cells.some((other) => cellEquals(cell, other));
9	}
10	
11	function isNeighbor(cell: Cell, other: Cell): boolean {
12	  const [x, y] = cell;
13	  const [otherX, otherY] = other;
14	  return (
15	    !cellEquals(cell, other) &&
16	    Math.abs(otherX - x) <= 1 &&
17	    Math.abs(otherY - y) <= 1
18	  );
19	}
20	
21	function countLiveNeighbors(cell: Cell, liveCells: Cell[]): number {
22	  return liveCells.filter((other) => isNeighbor(cell, other)).length;
23	}
24	
25	function survives(cell: Cell, liveCells: Cell[]): boolean {
26	  const liveNeighbors = countLiveNeighbors(cell, liveCells);
27	  return liveNeighbors === 2 || liveNeighbors === 3;
28	}
29	
30	function neighborsOf([x, y]: Cell): Cell[] {
31	  const neighbors: Cell[] = [];
32	  for (let dx = -1; dx <= 1; dx++) {
33	    for (let dy = -1; dy <= 1; dy++) {
34	      if (dx !== 0 || dy !== 0) {
35	        neighbors.push([x + dx, y + dy]);
36	      }
37	    }
38	  }
39	  return neighbors;
40	}
41	
42	function deadNeighborsOfLiveCells(liveCells: Cell[]): Cell[] {
43	  const deadNeighbors: Cell[] = [];
44	  for (const liveCell of liveCells) {
45	    for (const neighbor of neighborsOf(liveCell)) {
46	      if (!contains(liveCells, neighbor) && !contains(deadNeighbors, neighbor)) {
47	        deadNeighbors.push(neighbor);
48	      }
49	    }
50	  }
51	  return deadNeighbors;
52	}
53	
54	export function nextGeneration(liveCells: Cell[]): Cell[] {
55	  const survivors = liveCells.filter((cell) => survives(cell, liveCells));
56	  const born = deadNeighborsOfLiveCells(liveCells).filter(
57	    (cell) => countLiveNeighbors(cell, liveCells) === 3
58	  );
59	  return [...survivors, ...born];
60	}
