function uniqueCells(cells: Cell[]): Cell[] {
  return cells.filter(
    (cell, index) => cells.findIndex((other) => cellEquals(cell, other)) === index
  );
}

function deadNeighborsOfLiveCells(liveCells: Cell[]): Cell[] {
  const allNeighbors = liveCells.flatMap(neighborsOf);
